using System.Collections;
using OcctSharp.CopiedCollections;
using OcctSharp.NumericResults;
namespace OcctSharp.Runtime.Tests;
public sealed class NumericResultTests {
 [Fact]public void CopiedNumericResultsProduceGeometryAndIndependentFileReadback()=>OcctSharp.Tests.Shared.BatchBFNumericWorkflow.Run();
 [Fact]public void LuFactorsReconstructPivotedInputAndPreserveCopiedBounds(){double[] values=[0,2,1,3];var grid=new CopiedGrid<double>(values,2,2,-7,13);var r=NumericComputations.DecomposeLu(grid);Assert.True(r.IsDone);Assert.Equal(-2,r.Determinant);Assert.Equal(-7,r.Combined!.RowLower);Assert.Equal(13,r.Combined.ColumnLower);var factors=r.Combined.ToArray();var pivoted=(double[])values.Clone();for(int k=0;k<2;k++){int other=r.PivotOrdinals[k]-1;for(int j=0;j<2;j++)(pivoted[k*2+j],pivoted[other*2+j])=(pivoted[other*2+j],pivoted[k*2+j]);}for(int i=0;i<2;i++)for(int j=0;j<2;j++){double sum=0;for(int k=0;k<2;k++){double lower=i==k?1:i>k?factors[i*2+k]:0;double upper=k<=j?factors[k*2+j]:0;sum+=lower*upper;}Assert.Equal(pivoted[i*2+j],sum,12);}values[0]=99;Assert.Equal(0,grid.ToArray()[0]);}
 [Theory][InlineData(3,2)][InlineData(2,3)]public void SvdReconstructsRectangularMatricesAndResultsAreIndependent(int rows,int cols){double[] values=Enumerable.Range(0,rows*cols).Select(i=>Math.Sin(i+1)+i*.2).ToArray();var r=NumericComputations.DecomposeSvd(new(values,rows,cols,-3,8));Assert.True(r.IsDone);var u=r.Left!.ToArray();var v=r.Right!.ToArray();for(int i=0;i<rows;i++)for(int j=0;j<cols;j++){double sum=0;for(int k=0;k<cols;k++)sum+=u[i*cols+k]*r.SingularValues[k]*v[j*cols+k];Assert.Equal(values[i*cols+j],sum,9);}Array.Fill(values,99);Assert.NotEqual(99,u[0]);Assert.InRange(r.Rank!.Value,0,Math.Min(rows,cols));}
 [Fact]public void SingularLuNeverPublishesPartialFactorsOrSolution(){var matrix=new CopiedGrid<double>(new double[]{1,2,2,4},2,2);var lu=NumericComputations.DecomposeLu(matrix);Assert.False(lu.IsDone);Assert.Null(lu.Combined);Assert.Empty(lu.PivotOrdinals);Assert.Null(lu.Determinant);var solve=NumericComputations.Solve(matrix,[1,2]);Assert.False(solve.IsDone);Assert.Empty(solve.Solution);Assert.Null(solve.Determinant);Assert.False(NumericComputations.Invert(matrix).IsDone);}
 [Fact]public void SolveAndMultipleRhsHaveIndependentResidualEvidence(){var a=new CopiedGrid<double>(new double[]{3,1,1,2},2,2);var r=NumericComputations.Solve(a,[7,5]);Assert.True(r.IsDone);Assert.Equal(1.8,r.Solution[0],12);Assert.Equal(1.6,r.Solution[1],12);var many=NumericComputations.SolveMultiple(a,new(new double[]{7,1,5,0},2,2,-4,9));Assert.True(many.IsDone);var x=many.Matrix!.ToArray();Assert.Equal(9,many.Matrix.ColumnLower);for(int column=0;column<2;column++){Assert.Equal(column==0?7:1,3*x[column]+x[2+column],12);Assert.Equal(column==0?5:0,x[column]+2*x[2+column],12);}}
 [Fact]public void PseudoInverseAndSvdSolveSupportRankDeficiency(){var a=new CopiedGrid<double>(new double[]{1,2,2,4},2,2,-2,5);var r=NumericComputations.PseudoInverse(a);Assert.True(r.IsDone);Assert.Equal(5,r.Matrix!.RowLower);Assert.Equal(-2,r.Matrix.ColumnLower);var x=r.Matrix.ToArray();Assert.Equal(.04,x[0],10);Assert.Equal(.08,x[1],10);Assert.Equal(.16,x[3],10);var solve=NumericComputations.SolveSvd(a,[3,6]);Assert.True(solve.IsDone);Assert.Equal(.6,solve.Solution[0],9);Assert.Equal(1.2,solve.Solution[1],9);}
 [Fact]public void InverseAndDeterminantAgreeWithIndependentMatrixProduct(){var matrix=new CopiedGrid<double>(new double[]{4,1,2,3},2,2);var inverse=NumericComputations.Invert(matrix);Assert.True(inverse.IsDone);Assert.Equal(10,NumericComputations.Determinant(matrix).Determinant);var a=matrix.ToArray();var b=inverse.Matrix!.ToArray();for(int i=0;i<2;i++)for(int j=0;j<2;j++)Assert.Equal(i==j?1:0,a[i*2]*b[j]+a[i*2+1]*b[2+j],12);}
 [Fact]public void InvalidDimensionsBudgetsAndNonfiniteValuesFailBeforeResultPublication(){Assert.ThrowsAny<Exception>(()=>NumericComputations.Invert(new(new double[2],1,2)));Assert.Throws<ArgumentOutOfRangeException>(()=>NumericComputations.DecomposeSvd(new(new double[65],65,1)));Assert.Throws<ArgumentException>(()=>NumericComputations.Solve(new(new double[]{1},1,1),[1,2]));Assert.Throws<ArgumentOutOfRangeException>(()=>NumericComputations.Invert(new(new double[]{1},1,1),0));Assert.Throws<ArgumentException>(()=>NumericComputations.DecomposeLu(new(new double[]{double.NaN},1,1)));Assert.ThrowsAny<Exception>(()=>NumericComputations.Invert(new(new[]{double.Epsilon},1,1),double.Epsilon));}
 [Fact]public void VectorMetricsAndLazyBudgetsUseBoundedDetachedCopies(){var metrics=NumericComputations.InspectVectors([3,4],[2,-1]);Assert.Equal(5,metrics.EuclideanNorm);Assert.Equal(4,metrics.InfinityNorm);Assert.Equal(2,metrics.DotProduct);var endless=new Endless();Assert.Throws<ArgumentOutOfRangeException>(()=>NumericComputations.InspectVectors(endless,[1]));Assert.Equal(4097,endless.Count);Assert.True(endless.Disposed);}
 [Fact]public void ConcurrentPrivateSolversDoNotShareMutableResults(){Parallel.For(0,32,i=>{var r=NumericComputations.Solve(new(new double[]{2,0,0,4},2,2),[2.0*i,4.0*i]);Assert.True(r.IsDone);Assert.Equal(new double[]{i,i},r.Solution);});}
 sealed class Endless:IEnumerable<double>{public int Count;public bool Disposed;public IEnumerator<double> GetEnumerator(){try{while(true){Count++;yield return 1;}}finally{Disposed=true;}}IEnumerator IEnumerable.GetEnumerator()=>GetEnumerator();}
}
